async function getUser(id) {
  const key = `user:${id}`;

  const hit = await cache.get(key);
  if (hit) return JSON.parse(hit);

  const user = await db.users.findById(id);
  await cache.set(key, JSON.stringify(user), { EX: 300 }); // always set a TTL
  return user;
}

// key 'user:celebrity' expires at t=0, serving 5,000 req/s
//
//   t=0.000  5,000 concurrent requests all MISS
//   t=0.001  5,000 identical queries hit the database
//   t=0.002  connection pool exhausted
//
// The cache was absorbing that load. Nothing else was sized for it.

async function getUserSafe(id) {
  const key = `user:${id}`;

  const hit = await cache.get(key);
  if (hit) return JSON.parse(hit);

  // NX = only if absent → exactly one winner across the fleet
  const won = await cache.set(`lock:${key}`, '1', { NX: true, EX: 5 });

  if (!won) {
    await sleep(50);
    return getUserSafe(id);          // someone else is rebuilding
  }

  try {
    const user = await db.users.findById(id);
    await cache.set(key, JSON.stringify(user), { EX: 300 });
    return user;
  } finally {
    await cache.del(`lock:${key}`);  // always release
  }
}

async function updateUser(id, patch) {
  await db.users.update(id, patch);
  await cache.del(`user:${id}`);     // delete, don't set
}

// Residual race: reader loads old row, writer commits + deletes,
// reader then writes its stale value back. TTL bounds the damage.
// If that is unacceptable, you need versioned keys.
